int
soc_read_jr2_hbm_device_id(
    const int unit,
    const unsigned hbm_number,  
    soc_dnx_hbm_device_id_t * id)       
{
    sand_mbist_dynamic_t dynamic = { 0, 0, BSL_DEBUG, 0, 0 };
    uint32 out_vals[3];
    int passed_init = FALSE;
    SHR_FUNC_INIT_VARS(unit);

    SHR_NULL_CHECK(id, _SHR_E_PARAM, "id");

    
    if (SAL_BOOT_PLISIM)
    {
        goto only_exit;
    }

    
    SHR_IF_ERR_EXIT(soc_sand_cpu2tap_init_reset_enable(unit, &dnx_mbist_device, &dynamic));
    passed_init = TRUE;

    
    if (hbm_number == 0)
    {
        SAND_SHR_CPU2TAP_SCRIPT(emi0_HBM_SW_DEVICE_ID_cv, dnx_mbist_device, out_vals);
    }
    else
    {
        SAND_SHR_CPU2TAP_SCRIPT(emi1_HBM_SW_DEVICE_ID_cv, dnx_mbist_device, out_vals);
    }

    

    
    id->device_id_raw[0] = ((out_vals[0] >> 6) & 0xffffff) | (out_vals[1] << 24);       
    id->device_id_raw[1] = ((out_vals[1] >> 8) & 0x3fffff) | (out_vals[2] << 22);       
    id->device_id_raw[2] = ((out_vals[2] >> 10) & 0x3ffff);     

exit:
    if (passed_init) {
        MARK_CPU2TAP_ERROR_IF_HAPPENED(unit);
        SHR_IF_ERR_CONT(soc_sand_mbist_deinit_new(unit, &dnx_mbist_device, &dynamic));
    }

only_exit:
    SHR_FUNC_EXIT;
}


int
soc_read_jr2_hbm_temp(
    const int unit,
    const unsigned hbm_number,  
    uint32 *out_temp)           
{
    sand_mbist_dynamic_t dynamic = { 0, 0, BSL_DEBUG, 0, 0 };
    int passed_init = FALSE;
    SHR_FUNC_INIT_VARS(unit);

    
    if (SAL_BOOT_PLISIM || out_temp == NULL)
    {
        goto only_exit;
    }

    
    SHR_IF_ERR_EXIT(soc_sand_cpu2tap_init_reset_enable(unit, &dnx_mbist_device, &dynamic));
    passed_init = TRUE;

    
    if (hbm_number == 0)
    {
        SAND_SHR_CPU2TAP_SCRIPT(emi0_HBM_TEMPERATURE_no_init_cv_fixed, dnx_mbist_device, out_temp);
    }
    else
    {
        SAND_SHR_CPU2TAP_SCRIPT(emi1_HBM_TEMPERATURE_no_init_cv_fixed, dnx_mbist_device, out_temp);
    }

    
    *out_temp >>= 6;
    if (*out_temp & 128)
    {
        SHR_ERR_EXIT(_SHR_E_FAIL, "temperature result marked as invalid\n");
    }
    *out_temp &= 127;

exit:
    if (passed_init) {
        MARK_CPU2TAP_ERROR_IF_HAPPENED(unit);
        SHR_IF_ERR_CONT(soc_sand_mbist_deinit_new(unit, &dnx_mbist_device, &dynamic));
    }

only_exit:
    SHR_FUNC_EXIT;
}


int
soc_set_hbm_wrst_n_to_0(
    const int unit,
    const unsigned hbm_number)  
{
    sand_mbist_dynamic_t dynamic = { 0, 0, BSL_DEBUG, 0, 0 };
    int passed_init = FALSE;
    SHR_FUNC_INIT_VARS(unit);

    if (SAL_BOOT_PLISIM || !SOC_IS_JERICHO2_B(unit))
    { 
        goto only_exit;
    }

    
    SHR_IF_ERR_EXIT(soc_sand_cpu2tap_init_reset_enable(unit, &dnx_mbist_device, &dynamic));
    passed_init = TRUE;

    
    if (hbm_number == 0)
    {
        SAND_MBIST_TEST_SCRIPT_DO_NOT_STOP(emi0_HBM_SW_WRSTN0_cv, dnx_mbist_device);
    }
    else
    {
        SAND_MBIST_TEST_SCRIPT_DO_NOT_STOP(emi1_HBM_SW_WRSTN0_cv, dnx_mbist_device);
    }

exit:
    if (passed_init) {
        MARK_CPU2TAP_ERROR_IF_HAPPENED(unit);
        SHR_IF_ERR_CONT(soc_sand_mbist_deinit_new(unit, &dnx_mbist_device, &dynamic));
    }

only_exit:
    SHR_FUNC_EXIT;
}


int
soc_bist_all_jr2(
    const int unit,
    const int skip_errors)
{
    sand_mbist_dynamic_t dynamic = { 0, 0, 0, 0, 0 };
    int passed_init = FALSE;

    SHR_FUNC_INIT_VARS(unit);

    
    if (SAL_BOOT_PLISIM)
    {
        goto only_exit;
    }

    dynamic.skip_errors = skip_errors;
    
    soc_dnxc_set_need_system_reset(unit, 1);
    SHR_IF_ERR_EXIT(soc_sand_cpu2tap_init_reset_enable(unit, &dnx_mbist_device, &dynamic));
    passed_init = TRUE;

    
    if (SOC_IS_JERICHO2_B(unit))
    {
        SAND_SHR_MBIST_TEST_SCRIPT(mbist_postrep_half1_111218, dnx_mbist_device);
        SAND_SHR_MBIST_TEST_SCRIPT(jr2_mbist_postrep_half2_111218, dnx_mbist_device);
    }
    else
    {
        
        SAND_SHR_MBIST_TEST_SCRIPT(jr2_mbist_postrep_half1_090318, dnx_mbist_device);
        SAND_SHR_MBIST_TEST_SCRIPT(jr2_mbist_postrep_half2_090318, dnx_mbist_device);
    }
exit:
    if (passed_init) {
        
        MARK_CPU2TAP_ERROR_IF_HAPPENED(unit);
        SHR_IF_ERR_CONT(soc_sand_mbist_deinit_new(unit, &dnx_mbist_device, &dynamic));
    }

only_exit:
    SHR_FUNC_EXIT;
}


