int
soc_q2a_cpu2tap_init_mems(
    const int unit)
{
    sand_mbist_dynamic_t dynamic = { 0, 1, 0, 0, 0 };

    SHR_FUNC_INIT_VARS(unit);

    if (SAL_BOOT_PLISIM) 
    {
        goto only_exit;
    }

    
    SHR_IF_ERR_EXIT(soc_sand_mbist_init_new(unit, &dnx_mbist_device, &dynamic));

    
    if (SOC_IS_Q2A_A0(unit))
    {
        SAND_SHR_MBIST_TEST_SCRIPT(fill_emi_read_data_storage, dnx_mbist_device);
    }
    else if (SOC_IS_Q2N(unit))
    {
        SAND_SHR_MBIST_TEST_SCRIPT(q2n_fill_emi_dram_clock_mem, dnx_mbist_device);
    }
    else
    {
        SAND_SHR_MBIST_TEST_SCRIPT(q2a_b0_fill_emi_dram_clock_mem, dnx_mbist_device);
    }

exit:
    SHR_IF_ERR_CONT(soc_sand_cpu2tap_deinit_mbist(unit, &dnx_mbist_device, &dynamic));
only_exit:
    SHR_FUNC_EXIT;
}


int
soc_read_j2c_hbm_temp(
    const int unit,
    uint32 *out_temp)           
{
    sand_mbist_dynamic_t dynamic = { 0, 0, BSL_DEBUG, 0, 0 };
    int passed_init = FALSE;
    SHR_FUNC_INIT_VARS(unit);

    
    if (SAL_BOOT_PLISIM || out_temp == NULL)
    {
        goto only_exit;
    }
    dynamic.skip_errors = 1;
    
    SHR_IF_ERR_EXIT(soc_sand_cpu2tap_init_reset_enable(unit, &dnx_mbist_device, &dynamic));
    passed_init = TRUE;

    

    SAND_SHR_CPU2TAP_SCRIPT(emi_HBM_SW_TEMPERATURE_no_bisr_prsrv, dnx_mbist_device, out_temp);

    
    *out_temp >>= 6;
    if (*out_temp & 128)
    {
        SHR_ERR_EXIT(_SHR_E_FAIL, "temperature result marked as invalid\n");
    }
    
    *out_temp &= 127;


exit:
    if (passed_init) {
        MARK_CPU2TAP_ERROR_IF_HAPPENED(unit);
        SHR_IF_ERR_CONT(soc_sand_mbist_deinit_new(unit, &dnx_mbist_device, &dynamic));
    }

only_exit:
    SHR_FUNC_EXIT;
}


int
soc_read_j2c_hbm_device_id(
    const int unit,
    soc_dnx_hbm_device_id_t * id)       
{
    sand_mbist_dynamic_t dynamic = { 0, 0, BSL_DEBUG, 0, 0 };
    uint32 out_vals[3];
    int passed_init = FALSE;
    SHR_FUNC_INIT_VARS(unit);

    SHR_NULL_CHECK(id, _SHR_E_PARAM, "id");

    
    if (SAL_BOOT_PLISIM)
    {
        goto only_exit;
    }

    
    SHR_IF_ERR_EXIT(soc_sand_cpu2tap_init_reset_enable(unit, &dnx_mbist_device, &dynamic));
    passed_init = TRUE;

    

    SAND_SHR_CPU2TAP_SCRIPT(emi_HBM_SW_DEVICE_ID, dnx_mbist_device, out_vals);


    

    
    id->device_id_raw[0] = ((out_vals[0] >> 6) & 0xffffff) | (out_vals[1] << 24);       
    id->device_id_raw[1] = ((out_vals[1] >> 8) & 0x3fffff) | (out_vals[2] << 22);       
    id->device_id_raw[2] = ((out_vals[2] >> 10) & 0x3ffff);     

exit:
    if (passed_init) {
        MARK_CPU2TAP_ERROR_IF_HAPPENED(unit);
        SHR_IF_ERR_CONT(soc_sand_mbist_deinit_new(unit, &dnx_mbist_device, &dynamic));
    }

only_exit:
    SHR_FUNC_EXIT;
}


int
soc_dnx_read_hbm_device_id(
    const int unit,
    const unsigned hbm_number,  
    soc_dnx_hbm_device_id_t * id)       
{
    SHR_FUNC_INIT_VARS(unit);
    if (SOC_IS_J2C(unit)) {
        if (hbm_number) {
            SHR_ERR_EXIT(SOC_E_PARAM, "device has only one HBM.\n");
        }
        SHR_IF_ERR_EXIT(soc_read_j2c_hbm_device_id(unit, id));
    } else if (SOC_IS_JERICHO2(unit)) {
        if (hbm_number > 1) {
            SHR_ERR_EXIT(SOC_E_PARAM, "device has only two HBMs.\n");
        }
        SHR_IF_ERR_EXIT(soc_read_jr2_hbm_device_id(unit, hbm_number, id));
    } else {
        SHR_ERR_EXIT(SOC_E_PARAM, "Device not supported.\n");
    }

exit:
    SHR_FUNC_EXIT;
}

